import{_ as i,o,c as s,a2 as a}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"SYNPROXY (XDP SYN cookies)","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/detection-engine/synproxy.md","filePath":"openshield-xdp/detection-engine/synproxy.md","lastUpdated":1786336917000}'),t={name:"openshield-xdp/detection-engine/synproxy.md"};function n(r,e,l,d,h,c){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="synproxy-xdp-syn-cookies" tabindex="-1">SYNPROXY (XDP SYN cookies) <a class="header-anchor" href="#synproxy-xdp-syn-cookies" aria-label="Permalink to &quot;SYNPROXY (XDP SYN cookies)&quot;">​</a></h1><p>Cookie-based SYN-flood protection at XDP: during a SYN flood the firewall answers SYNs itself with cryptographic-cookie challenges, so spoofed floods never reach your services while real clients connect normally.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><ol><li>When the mode is engaged, a pure TCP SYN is answered directly at the NIC driver with a SYN-ACK whose sequence number is a kernel-standard SYN cookie. Nothing is stored per connection.</li><li>A spoofed source never answers — the half-open connection never reaches your stack, so SYN-queue and memory pressure from floods disappears.</li><li>A real client answers with an ACK whose cookie checks out, and the packet continues to your kernel, which instantiates the connection as if it had seen the original SYN. From the client&#39;s perspective the handshake is completely normal.</li><li>In <code>adaptive</code> mode all of this only happens while the SYN rate is over <code>synproxy_threshold</code> or an attack is active — everyday traffic is never challenged.</li></ol><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dynamic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  synproxy_mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;off&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # off (default) | adaptive | always</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  synproxy_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # per-CPU SYN pps that engages adaptive mode</span></span></code></pre></div><h2 id="one-time-setup-note" tabindex="-1">One-time setup note <a class="header-anchor" href="#one-time-setup-note" aria-label="Permalink to &quot;One-time setup note&quot;">​</a></h2><p>For the kernel to accept cookie-validated connections, <code>net.ipv4.tcp_syncookies</code> must be <code>1</code> (default on most distros) and the netfilter SYNPROXY companion hook must be registered once. When the mode is not <code>off</code>, the loader checks both and prints the exact two/three commands if anything is missing — in <code>adaptive</code> mode those lines can stay in place permanently; they are inert until a flood engages the cookie path.</p><div class="tip custom-block"><p class="custom-block-title">Defense in depth</p><p>The per-IP SYN rate limiter (<code>syn_pps_threshold</code> scoring) keeps running in all modes, including alongside the cookie path.</p></div><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Works for both IPv4 and IPv6.</li><li>Verification: 10/10 legitimate handshakes completed during an engaged cookie challenge on the test rig, while ~788k spoofed SYNs produced zero completed connections.</li></ul>`,11)])])}const u=i(t,[["render",n]]);export{k as __pageData,u as default};
